import xml.etree.ElementTree as ET

tree = ET.parse('/work/output/artifacts/skill-bpmn-feet-inches/FeetInchesBpmn/FeetInchesBpmn.bpmn')
root = tree.getroot()

ns = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'dc': 'http://www.omg.org/spec/DD/20100524/DC',
    'di': 'http://www.omg.org/spec/DD/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}

errors = []

# 1. Root is definitions
tag = root.tag
if 'definitions' not in tag.lower():
    errors.append(f"Root is not definitions: {tag}")
else:
    print(f"[OK] Root element: {tag}")

# Check uipath namespace present
if 'http://uipath.org/schema/bpmn' not in root.attrib.get('{http://www.w3.org/2000/xmlns/}uipath', '') and \
   'uipath' not in str(root.attrib):
    errors.append("uipath namespace not declared (checking another way)")

# 2. Collect all IDs
process = root.find('bpmn:process', ns)
all_ids = {}
for el in root.iter():
    eid = el.get('id')
    if eid:
        all_ids[eid] = el.tag

print(f"[OK] All element IDs: {list(all_ids.keys())}")

# 3. Collect flow nodes
flow_nodes = set()
for tag_name in ['startEvent', 'endEvent', 'scriptTask', 'task', 'exclusiveGateway',
                 'parallelGateway', 'inclusiveGateway', 'subProcess']:
    for el in process.findall(f'bpmn:{tag_name}', ns):
        flow_nodes.add(el.get('id'))

seq_flows = {}
for sf in process.findall('bpmn:sequenceFlow', ns):
    fid = sf.get('id')
    src = sf.get('sourceRef')
    tgt = sf.get('targetRef')
    seq_flows[fid] = (src, tgt)
    if src not in all_ids:
        errors.append(f"Flow {fid} sourceRef '{src}' not found")
    if tgt not in all_ids:
        errors.append(f"Flow {fid} targetRef '{tgt}' not found")

print(f"[OK] Flow nodes: {flow_nodes}")
print(f"[OK] Sequence flows: {seq_flows}")

# 4. Diagram completeness
diagram = root.find('bpmndi:BPMNDiagram', ns)
plane = diagram.find('bpmndi:BPMNPlane', ns)
shapes = {s.get('bpmnElement') for s in plane.findall('bpmndi:BPMNShape', ns)}
edges  = {e.get('bpmnElement') for e in plane.findall('bpmndi:BPMNEdge', ns)}

for fn in flow_nodes:
    if fn not in shapes:
        errors.append(f"Flow node '{fn}' has no BPMNShape")
    else:
        print(f"[OK] Shape for {fn}")

for fid in seq_flows:
    if fid not in edges:
        errors.append(f"SequenceFlow '{fid}' has no BPMNEdge")
    else:
        print(f"[OK] Edge for {fid}")

# 5. No gateways (no condition checks needed)
gws = process.findall('bpmn:exclusiveGateway', ns) + process.findall('bpmn:parallelGateway', ns)
if gws:
    errors.append(f"Unexpected gateways: {[g.get('id') for g in gws]}")

# 6. Each activity/event has at most one incoming
for tag_name in ['startEvent', 'endEvent', 'scriptTask', 'task']:
    for el in process.findall(f'bpmn:{tag_name}', ns):
        inc = el.findall('bpmn:incoming', ns)
        if len(inc) > 1:
            errors.append(f"Element {el.get('id')} has {len(inc)} incoming flows (FAKE_JOIN)")

# 7. Check uipath:scriptVersion is v3 on all scriptTasks
for st in process.findall('bpmn:scriptTask', ns):
    ext = st.find('bpmn:extensionElements', ns)
    if ext is not None:
        sv = ext.find('uipath:scriptVersion', ns)
        if sv is None:
            errors.append(f"ScriptTask {st.get('id')} missing uipath:scriptVersion")
        elif sv.get('value') != 'v3':
            errors.append(f"ScriptTask {st.get('id')} scriptVersion={sv.get('value')} (expected v3)")
        else:
            print(f"[OK] scriptVersion v3 on {st.get('id')}")
        mapping = ext.find('uipath:mapping', ns)
        if mapping is not None:
            utype = mapping.find('uipath:type', ns)
            if utype is None or utype.get('value') != 'BPMN.ScriptTask':
                errors.append(f"ScriptTask {st.get('id')} missing/wrong uipath:type child")
            else:
                print(f"[OK] uipath:type BPMN.ScriptTask on {st.get('id')}")

# 8. No double-hyphen in text
with open('/work/output/artifacts/skill-bpmn-feet-inches/FeetInchesBpmn/FeetInchesBpmn.bpmn') as f:
    content = f.read()
import re
bad_comments = re.findall(r'<!--.*?-->', content, re.DOTALL)
for c in bad_comments:
    if '--' in c[4:-3]:
        errors.append(f"XML comment contains '--': {c[:60]}")

if errors:
    print("\nERRORS:")
    for e in errors:
        print(f"  ERROR: {e}")
else:
    print("\nAll structural checks PASSED.")
